// Library theory for: range(start, stop, step), int(float), x ** 0.5, %

// "range(start, stop[, step]) -> range object
//  Return an object that produces a sequence of integers from start (inclusive)
//  to stop (exclusive) by step. ... When step is given, it specifies the increment (or decrement)."
function RangeStep(start: int, stop: int, step: int): seq<int>
  requires step != 0
  decreases if step > 0 then stop - start else start - stop
{
  if step > 0 then
    (if start >= stop then [] else [start] + RangeStep(start + step, stop, step))
  else
    (if start <= stop then [] else [start] + RangeStep(start + step, stop, step))
}

// "range(i, j) produces i, i+1, i+2, ..., j-1."
function Range(start: int, stop: int): seq<int>
{
  RangeStep(start, stop, 1)
}

// "int(x) ... If x is a number, return x.__int__(). For floating-point
//  numbers, this truncates towards zero."
function IntOfFloat(x: real): int
{
  if x >= 0.0 then x.Floor else -((-x).Floor)
}

// Python `x ** 0.5` for a float x >= 0: the (non-negative) square root of x.
// (Exact-real modeling assumption; for negative x Python yields a complex number, excluded here.)
function {:axiom} PyPowHalf(x: real): real
  requires x >= 0.0
  ensures PyPowHalf(x) >= 0.0
  ensures PyPowHalf(x) * PyPowHalf(x) == x

// Python `a % b`: result has the sign of b and satisfies a == (a // b) * b + a % b,
// with // flooring towards -infinity.
function PyFloorDiv(a: int, b: int): int
  requires b != 0
{
  if b > 0 then a / b
  else if a % b == 0 then a / b else a / b + 1
}

function PyMod(a: int, b: int): int
  requires b != 0
{
  a - PyFloorDiv(a, b) * b
}
