// Theory for Python's built-in `round`, under the convention float -> real (exact arithmetic).

// Helper: 10^n for natural n, used to express "precision in decimal digits".
function Pow10(n: nat): int
  ensures Pow10(n) >= 1
{
  if n == 0 then 1 else 10 * Pow10(n - 1)
}

// Helper: the scale factor 10^ndigits as a real. "ndigits may be negative."
function Pow10Real(ndigits: int): real
  ensures Pow10Real(ndigits) > 0.0
{
  if ndigits >= 0 then Pow10(ndigits) as real
  else 1.0 / (Pow10(-ndigits) as real)
}

// Helper: round a real to the nearest integer. Ties go to the even integer
// (Python language reference: "values are rounded to the closest multiple of 10
// to the power minus ndigits; if two multiples are equally close, rounding is
// done toward the even choice").
function RoundHalfEven(y: real): int
{
  var f := y.Floor;
  var frac := y - (f as real);
  if frac < 0.5 then f
  else if frac > 0.5 then f + 1
  else if f % 2 == 0 then f
  else f + 1
}

// "Round a number to a given precision in decimal digits."
// "Otherwise the return value has the same type as the number.  ndigits may be negative."
// round(number: float, ndigits: int) -> float: the closest multiple of 10^(-ndigits),
// with ties broken toward the even multiple.
function PyRound(x: real, ndigits: int): real
{
  (RoundHalfEven(x * Pow10Real(ndigits)) as real) / Pow10Real(ndigits)
}
